using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using Unity.Collections;
namespace FashionFit {
 public sealed class PoseBodyField:IDisposable {
  sealed class Data{public int x,y,z;public Vector3 origin;public float cell;public float[] d;public NativeArray<float> native;public int references;}
  static readonly Dictionary<string,Data> cache=new Dictionary<string,Data>();readonly Data field;readonly string gender;bool disposed;
  public NativeArray<float> NativeValues=>field.native;public Vector3 Origin=>field.origin;public float Cell=>field.cell;public int X=>field.x;public int Y=>field.y;public int Z=>field.z;
  public PoseBodyField(string gender){this.gender=gender;if(!cache.TryGetValue(gender,out field)){var asset=Resources.Load<TextAsset>("PoseWardrobe/"+gender+"BodyField");if(!asset)throw new InvalidDataException("Missing pose body field "+gender);using(var reader=new BinaryReader(new MemoryStream(asset.bytes))){if(reader.ReadInt32()!=0x50424631)throw new InvalidDataException("Invalid pose field");field=new Data{x=reader.ReadInt32(),y=reader.ReadInt32(),z=reader.ReadInt32(),origin=new Vector3(reader.ReadSingle(),reader.ReadSingle(),reader.ReadSingle()),cell=reader.ReadSingle()};string expected=reader.ReadString();var body=Resources.Load<TextAsset>("PoseModels/"+gender.ToLowerInvariant()+"-mesh");using(var hash=SHA256.Create()){string key=BitConverter.ToString(hash.ComputeHash(body.bytes)).Replace("-","").ToLowerInvariant();if(key!=expected)throw new InvalidDataException("Pose collision body changed");}int count=checked(field.x*field.y*field.z);if(count<8||count>8000000||field.cell<.002f||field.cell>.02f)throw new InvalidDataException("Invalid pose field dimensions");field.d=new float[count];var data=reader.ReadBytes(count*4);if(data.Length!=count*4)throw new InvalidDataException("Truncated field");Buffer.BlockCopy(data,0,field.d,0,data.Length);field.native=new NativeArray<float>(field.d,Allocator.Persistent);}cache.Add(gender,field);}field.references++;}
  public void Dispose(){if(disposed)return;disposed=true;if(--field.references==0){if(field.native.IsCreated)field.native.Dispose();cache.Remove(gender);}}
  float At(int x,int y,int z)=>field.d[(x*field.y+y)*field.z+z];
  float Sample(Vector3 p,out Vector3 normal){Vector3 q=(p-field.origin)/field.cell;int x=Mathf.FloorToInt(q.x),y=Mathf.FloorToInt(q.y),z=Mathf.FloorToInt(q.z);normal=Vector3.zero;if(x<0||y<0||z<0||x>=field.x-1||y>=field.y-1||z>=field.z-1)return 1;float u=q.x-x,v=q.y-y,w=q.z-z,a=At(x,y,z),b=At(x+1,y,z),c=At(x,y+1,z),d=At(x+1,y+1,z),e=At(x,y,z+1),f=At(x+1,y,z+1),g=At(x,y+1,z+1),h=At(x+1,y+1,z+1);float s0=Mathf.Lerp(Mathf.Lerp(a,b,u),Mathf.Lerp(c,d,u),v),s1=Mathf.Lerp(Mathf.Lerp(e,f,u),Mathf.Lerp(g,h,u),v),distance=Mathf.Lerp(s0,s1,w);if(distance>=.012f)return distance;normal.x=Mathf.Lerp(Mathf.Lerp(b-a,d-c,v),Mathf.Lerp(f-e,h-g,v),w)/field.cell;normal.y=Mathf.Lerp(Mathf.Lerp(c-a,d-b,u),Mathf.Lerp(g-e,h-f,u),w)/field.cell;normal.z=(s1-s0)/field.cell;return distance;}
  public Vector3 Project(Vector3 p){for(int pass=0;pass<3;pass++){float distance=Sample(p,out var n);if(distance>=.012f)break;if(n.sqrMagnitude<.03f){float best=float.NegativeInfinity;Vector3 selected=Vector3.up;for(int axis=0;axis<3;axis++)for(int sign=-1;sign<=1;sign+=2){Vector3 dir=(axis==0?Vector3.right:axis==1?Vector3.up:Vector3.forward)*sign;float value=Sample(p+dir*field.cell*2,out _);if(value>best){best=value;selected=dir;}}n=selected;}p+=n.normalized*Mathf.Min(.08f,.012f-distance);}return p;}
 }
}
